//! Cross-format tests against fixtures written by MATLAB R2024b
//! (`fixtures/zoo_*.mat`, generated by `scripts/make_fixtures.m`).

use matreader::model::{Class, Kind, MatFile, Node, Scalar, Shape, Window};
use std::path::PathBuf;
use std::sync::atomic::AtomicBool;

fn fixture(name: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("fixtures")
        .join(name)
}

fn open(name: &str) -> Box<dyn MatFile> {
    matreader::open(&fixture(name)).unwrap_or_else(|e| panic!("opening {}: {}", name, e))
}

fn load(file: &dyn MatFile, name: &str) -> Box<dyn Node> {
    let idx = file
        .variables()
        .iter()
        .position(|v| v.name == name)
        .unwrap_or_else(|| panic!("variable {} not found in {:?}", name, names(file)));
    file.load(idx, &AtomicBool::new(false))
        .unwrap_or_else(|e| panic!("loading {}: {}", name, e))
}

fn names(file: &dyn MatFile) -> Vec<String> {
    file.variables().iter().map(|v| v.name.clone()).collect()
}

fn all(node: &dyn Node) -> Vec<Scalar> {
    node.read_window(&Window::all(&node.shape())).unwrap()
}

fn floats(node: &dyn Node) -> Vec<f64> {
    all(node).iter().map(|s| s.as_f64()).collect()
}

fn text(node: &dyn Node) -> String {
    node.text_row(0, &[]).unwrap()
}

fn shape(dims: &[usize]) -> Shape {
    Shape::new(dims.to_vec())
}

fn check_zoo(name: &str, has_objects: bool) {
    let file = open(name);
    let vars = file.variables();
    let n = names(&*file);
    assert!(n.contains(&"scalarDouble".to_string()), "{:?}", n);

    // Variable listing metadata.
    let v = vars.iter().find(|v| v.name == "matrix").unwrap();
    assert_eq!(v.class, Class::Double);
    assert_eq!(v.shape, shape(&[6, 6]));
    let v = vars.iter().find(|v| v.name == "sparseMat").unwrap();
    assert!(v.is_sparse);
    assert_eq!(v.shape, shape(&[5, 4]));
    let v = vars.iter().find(|v| v.name == "complexMat").unwrap();
    assert!(v.is_complex);
    let v = vars.iter().find(|v| v.name == "nd4").unwrap();
    assert_eq!(v.shape, shape(&[2, 3, 4, 5]));
    let v = vars.iter().find(|v| v.name == "logicalMat").unwrap();
    assert_eq!(v.class, Class::Logical);
    let v = vars.iter().find(|v| v.name == "emptyZeros03").unwrap();
    assert_eq!(v.shape, shape(&[0, 3]));

    // Scalars and matrices.
    let s = load(&*file, "scalarDouble");
    assert_eq!(s.kind(), Kind::Numeric);
    assert_eq!(floats(&*s), vec![std::f64::consts::PI]);

    let m = load(&*file, "matrix");
    let magic6: Vec<f64> = vec![
        35., 3., 31., 8., 30., 4., 1., 32., 9., 28., 5., 36., 6., 7., 2., 33., 34., 29., 26., 21.,
        22., 17., 12., 13., 19., 23., 27., 10., 14., 18., 24., 25., 20., 15., 16., 11.,
    ];
    assert_eq!(floats(&*m), magic6);
    // Window read of a sub-block: rows 1..3, cols 2..4 (zero-based), column-major.
    let w = m.read_window(&Window::page(1..3, 2..4, &[])).unwrap();
    let got: Vec<f64> = w.iter().map(|s| s.as_f64()).collect();
    assert_eq!(got, vec![7., 2., 21., 22.]);

    let r = load(&*file, "rowVec");
    assert_eq!(r.shape(), shape(&[1, 10]));
    assert_eq!(floats(&*r), (1..=10).map(|x| x as f64).collect::<Vec<_>>());
    let c = load(&*file, "colVec");
    assert_eq!(c.shape(), shape(&[5, 1]));

    let tall = load(&*file, "tallMatrix");
    assert_eq!(tall.shape(), shape(&[3000, 3]));
    let w = tall
        .read_window(&Window::page(2998..3000, 1..3, &[]))
        .unwrap();
    let got: Vec<f64> = w.iter().map(|s| s.as_f64()).collect();
    assert_eq!(got, vec![5999., 6000., 8999., 9000.]);

    // Integer classes.
    let i = load(&*file, "int32Mat");
    assert_eq!(i.class(), Class::Int32);
    assert_eq!(i.shape(), shape(&[3, 4]));
    assert_eq!(
        all(&*i)[..3],
        [Scalar::Int(1), Scalar::Int(2), Scalar::Int(3)]
    );
    let i = load(&*file, "int16Neg");
    assert_eq!(all(&*i)[0], Scalar::Int(-3));
    let i = load(&*file, "int64Vec");
    // The MATLAB literal went through a double, so the stored value is 2^53.
    assert_eq!(all(&*i)[3], Scalar::Int(9007199254740992));
    let u = load(&*file, "uint64Max");
    assert_eq!(all(&*u)[0], Scalar::Uint(u64::MAX));
    let u = load(&*file, "uint8Mat");
    assert_eq!(u.class(), Class::Uint8);
    let s = load(&*file, "singleMat");
    assert_eq!(s.class(), Class::Single);
    assert!((floats(&*s)[0] - 8.0 / 7.0).abs() < 1e-6);

    // Logical.
    let l = load(&*file, "logicalMat");
    assert_eq!(l.class(), Class::Logical);
    let vals = all(&*l);
    assert_eq!(vals[0], Scalar::Bool(true)); // magic(4)(1,1) = 16 > 8
    assert_eq!(vals[1], Scalar::Bool(false)); // magic(4)(2,1) = 5
    let l = load(&*file, "logicalScalar");
    assert_eq!(all(&*l), vec![Scalar::Bool(true)]);

    // Complex.
    let z = load(&*file, "complexScalar");
    assert!(z.is_complex());
    assert_eq!(all(&*z), vec![Scalar::Complex(1.0, 2.0)]);
    let z = load(&*file, "complexMat");
    let vals = all(&*z);
    assert_eq!(vals[0], Scalar::Complex(8.0, 8.0));
    assert_eq!(vals[1], Scalar::Complex(3.0, 1.0));
    let z = load(&*file, "complexSingle");
    assert_eq!(all(&*z)[1], Scalar::Complex(2.0, -2.0));

    // Special values.
    let sp = floats(&*load(&*file, "specials"));
    assert!(sp[0].is_nan());
    assert_eq!(sp[1], f64::INFINITY);
    assert_eq!(sp[2], f64::NEG_INFINITY);
    assert_eq!(sp[8], f64::MAX);

    // Empties.
    let e = load(&*file, "emptyDouble");
    assert_eq!(e.shape(), shape(&[0, 0]));
    assert!(all(&*e).is_empty());
    let e = load(&*file, "emptyZeros03");
    assert_eq!(e.shape(), shape(&[0, 3]));

    // Chars.
    let ch = load(&*file, "charRow");
    assert_eq!(ch.kind(), Kind::Char);
    assert_eq!(text(&*ch), "hello world");
    let ch = load(&*file, "charMat");
    assert_eq!(ch.shape(), shape(&[3, 3]));
    assert_eq!(ch.text_row(0, &[]).unwrap(), "abc");
    assert_eq!(ch.text_row(2, &[]).unwrap(), "ghi");
    let ch = load(&*file, "charUnicode");
    if has_objects {
        assert_eq!(text(&*ch), "héllo wörld ✓ 你好");
    } else {
        // -v6 files cannot store characters outside Latin-1; MATLAB substitutes them.
        assert!(text(&*ch).starts_with("héllo wörld "), "{:?}", text(&*ch));
    }
    let ch = load(&*file, "emptyChar");
    assert_eq!(ch.shape(), shape(&[0, 0]));

    // Cells.
    let cell = load(&*file, "cellArr");
    assert_eq!(cell.kind(), Kind::Cell);
    assert_eq!(cell.shape(), shape(&[2, 3]));
    cell.prepare().unwrap();
    assert_eq!(floats(&*cell.cell(0).unwrap()), vec![1.0]);
    let inner = cell.cell(1).unwrap(); // (2,1) = {6}
    assert_eq!(inner.kind(), Kind::Cell);
    assert_eq!(floats(&*inner.cell(0).unwrap()), vec![6.0]);
    assert_eq!(text(&*cell.cell(2).unwrap()), "two");
    let st = cell.cell(3).unwrap(); // struct('a', 7)
    assert_eq!(st.kind(), Kind::Struct);
    assert_eq!(st.field_names().unwrap(), vec!["a"]);
    assert_eq!(floats(&*st.field(0, 0).unwrap()), vec![7.0]);
    assert_eq!(floats(&*cell.cell(4).unwrap()), vec![3.0, 4.0, 5.0]);
    let empty = cell.cell(5).unwrap();
    assert_eq!(empty.shape(), shape(&[0, 0]));
    let cell = load(&*file, "cellEmpty");
    assert_eq!(cell.shape(), shape(&[0, 0]));
    let cell = load(&*file, "cellCol");
    assert_eq!(cell.shape(), shape(&[3, 1]));
    cell.prepare().unwrap();
    assert_eq!(text(&*cell.cell(2).unwrap()), "gamma");
    let cell = load(&*file, "cellNested");
    cell.prepare().unwrap();
    let a = cell.cell(0).unwrap();
    a.prepare().unwrap();
    let b = a.cell(0).unwrap();
    b.prepare().unwrap();
    assert_eq!(text(&*b.cell(0).unwrap()), "deep");

    // Structs.
    let st = load(&*file, "scalarStruct");
    assert_eq!(st.kind(), Kind::Struct);
    assert_eq!(st.shape(), shape(&[1, 1]));
    assert_eq!(st.field_names().unwrap(), vec!["name", "value", "nested"]);
    assert_eq!(text(&*st.field(0, 0).unwrap()), "test");
    assert_eq!(floats(&*st.field(0, 1).unwrap()), vec![42.0]);
    let nested = st.field(0, 2).unwrap();
    assert_eq!(nested.field_names().unwrap(), vec!["deep", "mat", "txt"]);
    let deep = nested.field(0, 0).unwrap();
    deep.prepare().unwrap();
    assert_eq!(deep.shape(), shape(&[1, 3]));
    assert_eq!(floats(&*deep.cell(2).unwrap()), vec![3.0]);
    assert_eq!(floats(&*nested.field(0, 1).unwrap())[4], 1.0);
    assert_eq!(text(&*nested.field(0, 2).unwrap()), "inner");

    let sa = load(&*file, "structArr");
    assert_eq!(sa.kind(), Kind::Struct);
    assert_eq!(sa.shape(), shape(&[1, 3]));
    sa.prepare().unwrap();
    assert_eq!(sa.field_names().unwrap(), vec!["id", "label"]);
    assert_eq!(floats(&*sa.field(2, 0).unwrap()), vec![3.0]);
    assert_eq!(text(&*sa.field(1, 1).unwrap()), "two");
    let sa = load(&*file, "structArr2d");
    assert_eq!(sa.shape(), shape(&[2, 2]));
    sa.prepare().unwrap();
    assert_eq!(text(&*sa.field(3, 1).unwrap()), "z");
    let es = load(&*file, "emptyStruct");
    assert_eq!(es.shape(), shape(&[0, 0]));
    assert_eq!(es.kind(), Kind::Struct);
    let nf = load(&*file, "structNoFields");
    assert_eq!(nf.shape(), shape(&[1, 1]));
    assert!(nf.field_names().unwrap().is_empty());
    let nf = load(&*file, "structArrNoFields");
    assert_eq!(nf.shape(), shape(&[1, 3]));

    // Sparse.
    let sp = load(&*file, "sparseMat");
    assert_eq!(sp.kind(), Kind::Sparse);
    assert!(sp.is_sparse());
    assert_eq!(sp.shape(), shape(&[5, 4]));
    assert_eq!(sp.nnz(), 3);
    let e = sp.sparse_entries(0..10).unwrap();
    assert_eq!(e.len(), 3);
    assert_eq!((e[0].row, e[0].col, e[0].value.as_f64()), (0, 0, 10.0));
    assert_eq!((e[1].row, e[1].col, e[1].value.as_f64()), (2, 1, 20.0));
    assert_eq!((e[2].row, e[2].col, e[2].value.as_f64()), (4, 2, 30.0));
    let sp = load(&*file, "sparseLogical");
    assert_eq!(sp.class(), Class::Logical);
    assert_eq!(sp.nnz(), 3);
    assert_eq!(
        sp.sparse_entries(1..2).unwrap()[0].value,
        Scalar::Bool(true)
    );
    let sp = load(&*file, "sparseComplex");
    assert!(sp.is_complex());
    assert_eq!(
        sp.sparse_entries(1..2).unwrap()[0].value,
        Scalar::Complex(2.0, -2.0)
    );
    let sp = load(&*file, "sparseEmpty");
    assert_eq!(sp.shape(), shape(&[3, 3]));
    assert_eq!(sp.nnz(), 0);
    assert!(sp.sparse_entries(0..5).unwrap().is_empty());

    // N-D.
    let nd = load(&*file, "nd3");
    assert_eq!(nd.shape(), shape(&[2, 3, 4]));
    let w = nd.read_window(&Window::page(0..2, 0..3, &[3])).unwrap();
    let got: Vec<f64> = w.iter().map(|s| s.as_f64()).collect();
    assert_eq!(got, vec![19., 20., 21., 22., 23., 24.]);
    let nd = load(&*file, "nd4");
    let w = nd.read_window(&Window::page(1..2, 2..3, &[3, 4])).unwrap();
    assert_eq!(w[0].as_f64(), 120.0);
    let nd = load(&*file, "nd3single");
    assert_eq!(nd.class(), Class::Single);
    assert_eq!(floats(&*nd)[23], 24.0);

    // Function handles.
    let fh = load(&*file, "fh");
    assert_eq!(fh.kind(), Kind::Function);
    assert_eq!(fh.class(), Class::FunctionHandle);
    let fields = fh.field_names().unwrap();
    assert!(
        fields.contains(&"function_handle".to_string()),
        "{:?}",
        fields
    );
    let idx = fields.iter().position(|f| f == "function_handle").unwrap();
    let inner = fh.field(0, idx).unwrap();
    let ifields = inner.field_names().unwrap();
    let fi = ifields.iter().position(|f| f == "function").unwrap();
    // R2024b prefixes anonymous function text with an internal "sf%0" marker.
    assert!(text(&*inner.field(0, fi).unwrap()).ends_with("@(x)x.^2+1"));
    let fh = load(&*file, "fhNamed");
    let inner = fh.field(0, idx).unwrap();
    let ifields = inner.field_names().unwrap();
    let fi = ifields.iter().position(|f| f == "function").unwrap();
    assert_eq!(text(&*inner.field(0, fi).unwrap()), "sin");

    if has_objects {
        let s = load(&*file, "strScalar");
        assert_eq!(s.kind(), Kind::Opaque);
        assert_eq!(s.class(), Class::Opaque("string".into()));
        assert_eq!(s.shape(), shape(&[1, 1]));
        assert!(s.description().unwrap().contains("string"));
        let meta = s.inner().unwrap().expect("metadata");
        assert_eq!(meta.class(), Class::Uint32);
        assert_eq!(all(&*meta)[0], Scalar::Uint(0xDD00_0000));
        let t = load(&*file, "tbl");
        assert_eq!(t.class(), Class::Opaque("table".into()));
        let v = vars.iter().find(|v| v.name == "dt").unwrap();
        assert_eq!(v.class, Class::Opaque("datetime".into()));
    }
}

#[test]
fn zoo_v7() {
    check_zoo("zoo_v7.mat", true);
}

#[test]
fn zoo_v6() {
    check_zoo("zoo_v6.mat", false);
}

#[test]
fn zoo_v73() {
    check_zoo("zoo_v73.mat", true);
}

#[test]
fn zoo_v73_nocompression() {
    check_zoo("zoo_v73_nocomp.mat", true);
}

#[test]
fn format_strings() {
    assert!(open("zoo_v7.mat").format().contains("compressed"));
    assert!(open("zoo_v6.mat").format().contains("v6"));
    assert!(open("zoo_v73.mat").format().contains("7.3"));
    assert!(open("zoo_v7.mat")
        .header_text()
        .starts_with("MATLAB 5.0 MAT-file"));
    assert!(open("zoo_v73.mat")
        .header_text()
        .starts_with("MATLAB 7.3 MAT-file"));
}

#[test]
fn chunked_reads_match_whole_reads() {
    // Every numeric value read through the windowed path must match a
    // straightforward full read, across compressed and contiguous layouts.
    for name in ["zoo_v73.mat", "zoo_v73_nocomp.mat"] {
        let file = open(name);
        for v in file.variables() {
            if !v.class.is_numeric() || v.is_sparse || v.shape.is_empty() {
                continue;
            }
            let node = load(&*file, &v.name);
            let whole = all(&*node);
            let sh = node.shape();
            // Read element-by-element windows in a scattered order.
            for k in (0..sh.numel()).step_by((sh.numel() / 7).max(1)) {
                let subs = sh.subscripts(k);
                let win = Window {
                    start: subs.clone(),
                    len: vec![1; subs.len()],
                };
                let one = node.read_window(&win).unwrap();
                assert_eq!(one.len(), 1, "{} {}", name, v.name);
                if let (Scalar::Float(a), Scalar::Float(b)) = (&one[0], &whole[k]) {
                    if a.is_nan() && b.is_nan() {
                        continue;
                    }
                }
                assert_eq!(one[0], whole[k], "{} {} element {}", name, v.name, k);
            }
        }
    }
}
